/* ============================================================
   Modelos 3D realistas do cervo: MACHO (com chifres) e FÊMEA (sem chifres), embutidos em base64.
   Precisa de THREE.GLTFLoader (e, de preferência, THREE.SkeletonUtils) carregados.
   Se não existirem, o cervo continua com o modelo antigo (Kit.land).
   Créditos dos modelos (Sketchfab):
     - Macho: "deer" por neighbor (kylekip), licença CC BY 4.0
     - Fêmea: "Deer (Non-Commercial)" por Nyilonelycompany, licença CC BY-NC 4.0 (uso não comercial)
   ============================================================ */
const CervoGLB = (() => {
  const B64 = { macho: '', femea: '' };
  const MACHO_A_CADA = 2;   // 1 macho a cada 2 cervos (2 = metade/metade, 3 = 1 macho para 2 fêmeas...)
  const MODELO = {          // alt = altura original do GLB; esc = altura final ÷ 'top'; y/z = ajuste de apoio e centro
    macho: { alt: .512, esc: 1,   y: .256, z: -.256 },   // altura inclui os chifres
    femea: { alt: 1.349, esc: .75, y: .002, z: -.18 }    // um pouco menor que o macho
  };
  const REF_VEL = 1.5;      // velocidade (× 'top', unid./s) em que o passo anima em 1x

  const cache = { macho: { gltf: null, carregando: false, fila: [] }, femea: { gltf: null, carregando: false, fila: [] } };
  const vivos = []; let P = null, contador = 0;   // P é criado só quando o THREE existir

  const bytes = s => { const t = atob(B64[s]), u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i); return u.buffer; };
  const falha = e => console.warn('Cervo (GLB):', e);

  // Cada cervo precisa do seu próprio esqueleto: clonamos com SkeletonUtils (ou lemos o arquivo de novo).
  function obter(s, cb) {
    if (!THREE.SkeletonUtils) return new THREE.GLTFLoader().parse(bytes(s), '', g => cb(g.scene, g.animations), falha);
    const c = cache[s], pronto = g => cb(THREE.SkeletonUtils.clone(g.scene), g.animations);
    if (c.gltf) return pronto(c.gltf);
    c.fila.push(pronto);
    if (c.carregando) return;
    c.carregando = true;
    new THREE.GLTFLoader().parse(bytes(s), '', g => { c.gltf = g; c.fila.splice(0).forEach(f => f(g)); }, falha);
  }

  // Andando: balanço de passo (o modelo do macho não tem esqueleto). Parado: a fêmea toca a animação de pastar.
  let rodando = false, t0 = 0;
  function ciclo() {
    if (rodando) return; rodando = true; t0 = performance.now(); P = new THREE.Vector3();
    const passo = () => {
      requestAnimationFrame(passo);
      const t = performance.now(), dt = Math.min((t - t0) / 1000, .1); t0 = t;
      for (const v of vivos) {
        v.base.getWorldPosition(P);
        const vel = v.ini ? P.distanceTo(v.ult) / Math.max(dt, 1e-3) : 0;
        v.ult.copy(P); v.ini = true; v.vel = v.vel * .85 + vel * .15;
        if (v.vel > .15 * v.top) {
          v.fase += dt * 7 * Math.min(2.2, Math.max(.5, v.vel / (REF_VEL * v.top)));
          v.pivo.position.y = Math.abs(Math.sin(v.fase)) * .025 * v.top;
          v.pivo.rotation.z = Math.sin(v.fase * .5) * .03;
          v.pivo.rotation.x = Math.cos(v.fase) * .015;
          if (v.acao) { v.acao.time = 0; v.mixer.update(0); }   // cabeça erguida enquanto anda
        } else {
          v.pivo.position.y = 0; v.pivo.rotation.set(0, 0, 0);
          if (v.acao) v.mixer.update(dt);                        // parada: pasta
        }
      }
    };
    passo();
  }

  function anexar(base, sp) {
    const sexo = (contador++ % MACHO_A_CADA === 0) ? 'macho' : 'femea';
    base.userData.sexo = sexo;
    obter(sexo, (modelo, clips) => {
      const velhos = []; base.traverse(o => { if (o.isMesh) velhos.push(o); });
      velhos.forEach(o => o.parent && o.parent.remove(o));   // remove o modelo antigo de vez (só esconder pode ser desfeito pelo sistema)
      const m = MODELO[sexo], top = (sp && sp.top) || 2.6, pivo = new THREE.Group();
      modelo.position.set(0, m.y, m.z);
      pivo.add(modelo); pivo.scale.setScalar(m.esc * top / m.alt); base.add(pivo);
      const solido = m => { m.transparent = false; m.opacity = 1; m.depthWrite = true; m.depthTest = true; m.blending = THREE.NormalBlending; m.alphaTest = 0; m.visible = true; m.side = THREE.DoubleSide; m.needsUpdate = true; };   // corpo sempre opaco
      modelo.traverse(o => { if (o.isMesh) { o.material = Array.isArray(o.material) ? o.material.map(m => m.clone()) : o.material.clone(); [].concat(o.material).forEach(solido); o.castShadow = true; o.receiveShadow = true; o.frustumCulled = false; } });
      const v = { base, pivo, top, sexo, ult: new THREE.Vector3(), ini: false, vel: 0, fase: Math.random() * 6 };
      if (clips && clips.length) { v.mixer = new THREE.AnimationMixer(modelo); v.acao = v.mixer.clipAction(clips[0]); v.acao.play(); }
      vivos.push(v); ciclo();
    });
  }
  return { anexar };
})();

/* ============================================================
   Cervo: tudo sobre este animal fica nesta pasta.
   Seções: 1) dados e card · 2) ícone · 3) modelo 3D · 4) comportamento
   ============================================================ */
registerAnimal('cervo', {

  /* 1) DADOS: card informativo, quantidade inicial/máxima, cor do destaque e área de clique */
  data: {
      name: "Cervo",
      sci: "Família Cervidae",
      diet: "Herbívoro",
      role: "Consumidor primário",
      habitat: "Interior da mata e campos próximos a fontes de água.",
      desc: "Herbívoro de grande porte que se alimenta de folhas, brotos e frutos caídos. Fica sempre atento a predadores.",
      fact: "Os machos têm chifres ramificados que caem e crescem de novo a cada ano.",
      qty: 6,
      max: 24,
      color: "#ffa726",
      hit: 1.5,
      hy: 1.4,
      top: 2.6,
      kind: "land"
  },

  /* 2) ÍCONE (legenda e card) */
  icon: `<svg viewBox="0 0 48 48" aria-hidden="true"><g stroke="#e6d5a8" stroke-width="3" fill="none" stroke-linecap="round"><path d="M16 18L10 6M10 6l-4 3M10 10l-5 1M32 18l6-12M38 6l4 3M38 10l5 1"/></g><ellipse cx="13" cy="19" rx="4" ry="2.5" fill="#ba8c63" transform="rotate(-30 13 19)"/><ellipse cx="35" cy="19" rx="4" ry="2.5" fill="#ba8c63" transform="rotate(30 35 19)"/><ellipse cx="24" cy="29" rx="11" ry="13" fill="#ba8c63"/><ellipse cx="24" cy="37" rx="6" ry="5" fill="#e9d3b4"/><circle cx="19" cy="27" r="1.8" fill="#222"/><circle cx="29" cy="27" r="1.8" fill="#222"/><ellipse cx="24" cy="39" rx="2.2" ry="1.6" fill="#222"/></svg>`,

  /* 3) MODELO 3D: cervo realista, machos (com chifres) e fêmeas alternados, sobre o rig do Kit.land que continua cuidando de estados e movimento */
  build(sp) {
    const base = Kit.land({ body: [.5, .2, .15], lh: .6, neck: .42, head: [.13, .1, .08], snout: .13,
      ear: [.05, .1], tail: [.08, .06], legs: .03, antlers: 1, c: [0xb07a4a, 0xe9d3b4, 0x5a3d26] }, sp);
    if (window.THREE && THREE.GLTFLoader) CervoGLB.anexar(base, sp);   // sem GLTFLoader: mantém o modelo antigo
    return base;
  },

  /* 4) COMPORTAMENTO: pasta, bebe água na lagoa ou caminha. Não foge de ninguém. */
  decide(a, H) {
    const p = Math.random();
    if (p < .5) return H.st(a, 'graze', H.r(5, 10));
    if (p < .68) return H.go(a, H.pondPt(), 'drink', H.r(3, 6));
    H.go(a, H.landPoint(), 'idle', H.r(1, 2));
  }
});
